NODE = r'''const fs=require('fs'), crypto=require('crypto');
let raw='';process.stdin.on('data',x=>raw+=x);process.stdin.on('end',()=>{
 const manifest=JSON.parse(raw), mismatches=[];let matched=0;
 for(const [file,hash] of Object.entries(manifest)){
  try {const stat=fs.lstatSync('/app/'+file); if(!stat.isFile()||stat.isSymbolicLink())throw Error();
   const actual=crypto.createHash('sha256').update(fs.readFileSync('/app/'+file)).digest('hex');
   if(actual===hash)matched++;else mismatches.push(file);
  }catch{mismatches.push(file)}
 }
 console.log(JSON.stringify({matched,total:Object.keys(manifest).length,mismatches}));
});'''
def main():
    image=subprocess.check_output(['docker','inspect','--format','{{.Image}}','v79-hub'],text=True).strip()
    if image != EXPECTED_IMAGE: sys.exit('SOURCE_PARITY=STOP_RUNTIME_IMAGE_CHANGED')
    result=subprocess.run(['docker','exec','-i','v79-hub','node','-e',NODE],input=json.dumps(EXPECTED),text=True,capture_output=True,timeout=60)
    if result.returncode: sys.exit('SOURCE_PARITY=UNAVAILABLE')
    data=json.loads(result.stdout)
    image_after=subprocess.check_output(['docker','inspect','--format','{{.Image}}','v79-hub'],text=True).strip()
    if image_after != image: sys.exit('SOURCE_PARITY=STOP_RUNTIME_CHANGED_DURING_READ')
    print('MODE=READ_ONLY_NO_PRODUCTION_CHANGES')
    print('BASELINE=ffae1c104d6ded918a0028f92c76624bc0501d8b')
    print('RUNTIME_BUILD_INPUTS_MATCHED='+str(data['matched'])+'/'+str(data['total']))
    print('SOURCE_PARITY='+('PASS_TRACKED_INPUTS' if not data['mismatches'] else 'MISMATCH'))
    for file in data['mismatches']: print('MISMATCH_PATH='+file)
    print('SCOPE=TRACKED_HUB_RUNTIME_AND_BUILD_INPUTS_ONLY;NOT_DATA_ENVIRONMENT_OR_IMAGE_EQUIVALENCE')
    if data['mismatches']: sys.exit(1)
if __name__=='__main__': main()
